using System;using System.Net;using Microsoft.AspNetCore.Builder;using Microsoft.AspNetCore.Diagnostics;using Microsoft.AspNetCore.Http;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Logging;using accounts-management.Data;using accounts-management.Services;using System.Text.Json;var builder=WebApplication.CreateBuilder(args);builder.WebHost.UseKestrel().UseUrls("http://0.0.0.0:8080");builder.Services.AddControllers().AddJsonOptions(options=>{options.JsonSerializerOptions.PropertyNamingPolicy=JsonNamingPolicy.CamelCase;options.JsonSerializerOptions.WriteIndented=false;});builder.Services.AddEndpointsApiExplorer();builder.Services.AddLogging(logging=>{logging.ClearProviders();logging.AddConsole();logging.AddDebug();});var configuration=builder.Configuration;var provider=configuration.GetValue<string>("Database:Provider")??"MySql";var connectionString=configuration.GetConnectionString("DefaultConnection")??"";if(string.IsNullOrWhiteSpace(connectionString))throw new InvalidOperationException("Connection string 'DefaultConnection' is not configured.");if(provider.Equals("MySql",StringComparison.OrdinalIgnoreCase)){builder.Services.AddDbContext<ApplicationDbContext>(options=>{var serverVersion=ServerVersion.AutoDetect(connectionString);options.UseMySql(connectionString,serverVersion, mySqlOptions=>{mySqlOptions.EnableRetryOnFailure(5,TimeSpan.FromSeconds(10),null);});});}else{throw new NotSupportedException($"Database provider '{provider}' is not supported.");}builder.Services.AddScoped<IAccountService,AccountService>();var app=builder.Build();app.UseExceptionHandler(appError=>{appError.Run(async context=>{var feature=context.Features.Get<IExceptionHandlerFeature>();var logger=context.RequestServices.GetRequiredService<ILoggerFactory>().CreateLogger("GlobalExceptionHandler");if(feature?.Error!=null){logger.LogError(feature.Error,"Unhandled exception");}context.Response.StatusCode=(int)HttpStatusCode.InternalServerError;context.Response.ContentType="application/json";await context.Response.WriteAsync(JsonSerializer.Serialize(new{title="An unexpected error occurred.",status=500,traceId=context.TraceIdentifier}));});});app.UseRouting();app.MapControllers();app.Run();